function migrate(){
 state.todos??=[];state.opportunities??=[];state.trashedResumes??=[];state.posts??=clone(bank);state.publicJobs??=[];state.sessions??=[];state.recruitmentApplications??=[];state.talentRequests??=[];
 state.events??=Object.keys(modes).map(m=>({id:'event-'+m,mode:m,company:'青禾科技',job:modes[m].role,track:'后端',round:'技术一面',date:dayOffset(1),time:'14:00',location:'视频面试',resumeId:state.resumes[1]?.id||state.resumes[0]?.id,status:'待参加',sample:true}));
 state.reviews.forEach(r=>{r.id??=uid();r.tags??='面试';r.kind??='真实面试';r.updated??=dayKey()});state.resumes.forEach(r=>{r.template??='classic'});
 state.interest??={direction:'后端',cities:'杭州 上海',terms:'Java Redis'};
}
