let selectedDay=dayKey(),weekShift=0,selectedReview=null,reviewPreview=false,activeSession=null,recognition=null,listening=false,voiceEnabled=false;
const oldRender=render,oldAction=action,oldResumeView=resumes,oldPaper=resumePaper,oldGo=go;
navItems=function(){
 if(role==='admin')return [['admin','settings','合作方管理'],['recruiter','bag','岗位审核'],['community','file','面经审核'],['services','calendar','服务与回访']];
 if(role==='hunter')return [['hunterdesk','people','猎头工作台'],['recruiter','bag','受托岗位']];
 if(role==='recruiter')return [['recruiter','bag','企业招聘台']];
 if(role==='provider')return [['provider','calendar','服务协作']];
 return [['today','home','今天'],['resumes','file','我的简历'],['jobs','bag','岗位与公司'],['opportunities','bag','我的机会'],['applications','grid','投递管理'],['practice','calendar','面试与模拟'],['reviews','file','复盘库'],['community','people','面经社区'],['market','grid','模板与简历市场'],['services','people','人工服务'],...(mode==='social'?[['hunters','people','找猎头']]:[])];
};
titleMap.practice='面试与模拟';titleMap.applications='投递管理';titleMap.market='模板与简历市场';
function roleEntry(){modal('选择工作入口',`<p class="note">下面可体验开通后的演示工作台。真实身份需经过核验，切换演示不会创建账号。</p><div class="stack" style="margin-top:20px">${[['user','个人求职者','实习、校招、社招'],['hunter','猎头入口','负责人线下核验、邀请开通；只服务社招'],['recruiter','企业招聘者入口','核验企业任职关系后，发布招聘与处理申请'],['provider','服务合作入口','负责人对接；按服务单确认与交付'],['admin','平台负责人','核验合作、审核岗位与面经、处理回访']].map(([id,t,desc])=>`<button class="mode-option" data-act="set-role" data-id="${id}"><span class="square-icon">${I('people')}</span><div class="grow"><h3>${t}</h3><p class="label">${desc}</p></div>${I('arrow')}</button>`).join('')}</div>`)}
render=function(){migrate();if(mode&&!navItems().some(x=>x[0]===page)&&page!=='chat')page=navItems()[0][0];oldRender();if(mode&&role!=='user'){const sw=document.querySelector('.workspace-switch');if(sw)sw.textContent={recruiter:'企业招聘空间',hunter:'猎头工作空间',admin:'平台管理空间',provider:'服务协作空间'}[role];const profile=document.querySelector('.profile .avatar');if(profile)profile.textContent={recruiter:'青',hunter:'周',admin:'管',provider:'陈'}[role]}if(!mode){document.querySelector('.intro-foot').insertAdjacentHTML('afterend',`<div class="entry-links"><a class="text-btn" href="#entry-hunter" data-act="entry-hunter">猎头入口</a><a class="text-btn" href="#entry-recruiter" data-act="entry-recruiter">企业招聘者入口</a><a class="text-btn" href="#entry-service" data-act="service-partner">服务合作</a></div>`)}else{const label=document.querySelector('.top-actions .label');if(label)label.textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});document.querySelector('.app-footer').insertAdjacentHTML('beforeend',act('role','工作入口','text-btn'))}};
go=function(p){if(page==='chat'&&p!=='chat'){saveChatDraft();stopVoice()}oldGo(p)};
function saveChatDraft(){const s=state.sessions.find(x=>x.id===activeSession),el=document.getElementById('chat-answer');if(s&&el){s.draft=el.value;persist()}}
function ownEvents(){return state.events.filter(x=>x.mode===mode)}
function weekCalendar(){const monday=new Date();monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-(monday.getDay()+6)%7+weekShift*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return d});return `<section class="card"><div class="section-head"><h2>本周日程</h2><div class="row">${act('week-prev','‹','btn sm','aria-label="上一周"')}${act('week-now','今天','text-btn')}${act('week-next','›','btn sm','aria-label="下一周"')}</div></div><p class="meta">${dayKey(days[0])} — ${dayKey(days[6])}</p><div class="week">${days.map((d,i)=>`<button class="${dayKey(d)===selectedDay?'selected':''}" data-act="day" data-id="${dayKey(d)}" aria-label="${dayKey(d)}" aria-pressed="${dayKey(d)===selectedDay}"><span>${['一','二','三','四','五','六','日'][i]}</span><b>${d.getDate()}</b>${ownEvents().some(e=>e.date===dayKey(d))?'<i></i>':''}</button>`).join('')}</div><p class="label">${selectedDay}</p>${ownEvents().filter(e=>e.date===selectedDay).map(e=>`<button class="schedule-item" data-act="event" data-id="${e.id}"><span class="schedule-line"></span><div><strong>${E(e.company)} · ${E(e.round)}</strong><p>${E(e.time)} · ${E(e.location)}</p>${pill(e.status)}</div></button>`).join('')||'<p class="empty">这天没有面试安排。</p>'}${act('new-event','添加面试日程','btn full')}</section>`}
function recommendedJobs(){const ts=(state.interest.direction+' '+state.interest.terms).split(/\s+/).filter(Boolean);return availableJobs().map(j=>({j,score:ts.filter(t=>(j.skills+j.job).includes(t)).length*3+(state.interest.cities.includes(j.city)?2:0)})).sort((a,b)=>b.score-a.score||(b.j.date||'').localeCompare(a.j.date||'')).slice(0,2).map(x=>x.j)}
today=function(){const todos=state.todos.filter(t=>t.mode===mode),pending=todos.filter(t=>!t.done),apps=state.applications.filter(a=>a.mode===mode);return head('下午好，一舟 <span class="greeting">✳</span>',`按自己的节奏推进，还有 ${pending.length} 项待办。`,act('todo-new',I('plus')+' 添加待办','btn primary'))+`<div class="stats">${[['我的待办',pending.length,'today'],['进行中的投递',apps.filter(a=>!['已结束','Offer'].includes(a.stage)).length,'applications'],['待参加面试',ownEvents().filter(e=>e.status==='待参加').length,'practice'],['我的简历',state.resumes.length,'resumes']].map(([t,n,p])=>`<button class="card stat" data-page="${p}"><span class="label">${t}</span><strong>${String(n).padStart(2,'0')}</strong><small>查看 ${I('arrow')}</small></button>`).join('')}</div><div class="dashboard-grid"><div class="stack"><section class="card"><div class="section-head"><h2>我的待办</h2>${act('todo-new','添加','text-btn')}</div>${todos.length?todos.map(t=>`<div class="task"><input type="checkbox" aria-label="完成 ${E(t.title)}" data-todo="${t.id}" ${t.done?'checked':''}><div class="grow"><h3 class="${t.done?'completed':''}">${E(t.title)}</h3><p class="meta">${E(t.category)} · ${E(t.date||'未设日期')}</p></div>${act('todo-edit','编辑','text-btn',`data-id="${t.id}"`)}</div>`).join(''):'<div class="empty"><h3>今天的安排，由你来定</h3><p>准备面试、修改简历、查看通知，或任何你想记下的事。</p></div>'}</section><section class="card"><div class="section-head"><h2>值得看看</h2><button class="text-btn" data-page="jobs">全部平台岗位 ${I('arrow')}</button></div><p class="label">按你的方向、城市与岗位更新时间排序 · 演示推荐 ${act('interest','调整偏好','text-btn')}</p><div class="recommend-grid">${recommendedJobs().map(c=>`<button class="recommend-job" data-act="job" data-id="${c.id}"><div class="row">${logo(c)}<div><h3>${E(c.name)}</h3><span class="meta">${E(c.city)} · ${E(c.date||dayKey())}</span></div></div><p>${E(c.job)}</p><span class="meta">${E(c.skills)}</span></button>`).join('')}</div></section></div><div class="stack">${weekCalendar()}<section class="card guide-card"><h3>练习、记录，再进步一点。</h3><p class="label">每场模拟的问答都会保存到私密复盘库。</p><button class="text-btn" data-page="reviews">打开复盘库 ${I('arrow')}</button></section></div></div>`};
function todoForm(id){const t=state.todos.find(t=>t.id===id);formModal(t?'编辑待办':'添加待办',field('事项','title',t?.title||'')+selectField('分类','category',['准备面试','修改简历','查看通知','学习练习','其他'],t?.category)+`<label class="field"><span>日期（可选）</span><input type="date" name="date" value="${t?.date||dayKey()}"></label>`+(t?act('todo-delete','删除这条待办','text-btn',`data-id="${id}"`):''),'保存待办',f=>{const x={title:f.get('title').trim(),category:f.get('category'),date:f.get('date')};if(!x.title)return; if(t)Object.assign(t,x);else state.todos.push({id:uid(),mode,done:false,...x});persist();close();render()})}
function availableJobs(){return [...companies.map(c=>({...c,job:c.id==='j3'?'数据开发工程师':modes[mode].role,mode,date:'2026-09-16',source:'平台演示岗位',official:''})),...state.publicJobs.filter(j=>j.status==='已发布'&&j.mode===mode)]}
jobs=function(){const list=availableJobs().filter(c=>(c.name+c.city+c.skills+c.job).toLowerCase().includes(query.toLowerCase())&&(filter!=='已收藏'||state.favorites.includes(c.id)));return head('岗位与公司','浏览平台公开岗位。站外看到的机会，可以单独存入「我的机会」。')+toolbar('搜索公司、城市或技术方向',['全部','已收藏'])+`<div class="row between list-caption"><span class="label">${modes[mode].label} · ${list.length} 个岗位</span>${pill('企业发布 / 平台收录','blue')}</div><div class="job-grid">${list.map(c=>`<article class="card job-card"><div class="row between"><div class="row">${logo(c)}<div><h3>${E(c.name)}</h3><span class="meta">${E(c.source)}</span></div></div>${act('favorite',state.favorites.includes(c.id)?'已收藏':'收藏','btn sm',`data-id="${c.id}"`)}</div><h2>${E(c.job)}</h2><div class="salary">${E(c.salary)}</div><p class="label">${E(c.city)} · ${E(c.date)}</p><div class="skill-row">${E(c.skills)}</div><div class="job-card-footer">${pill(c.ref?'有内推入口':'企业直招','green')}${act('job','查看岗位 '+I('arrow'),'text-btn',`data-id="${c.id}"`)}</div></article>`).join('')||empty('没有匹配岗位，试试其他关键词。')}</div>`};
jobDetail=function(id){const c=availableJobs().find(x=>x.id===id);if(!c)return;modal('岗位详情',`<div class="row">${logo(c)}<div><h2>${E(c.name)}</h2><p class="label">${E(c.city)} · ${modes[mode].label}</p></div></div><h2 style="margin:20px 0">${E(c.job)}</h2><p>${E(c.desc)}</p><div class="skill-row">${E(c.skills)}</div><p class="label">来源：${E(c.source)} · ${E(c.date)}</p>${safeUrl(c.official)?`<p style="margin:16px 0"><a class="btn" href="${E(safeUrl(c.official))}" target="_blank" rel="noopener noreferrer">前往官网招聘原文 ↗</a></p>`:'<p class="note" style="margin:16px 0">虚构样例未提供官网链接。HR/管理员发布的岗位可填写并跳转招聘原文。</p>'}`,act('close','关闭','btn ghost')+(c.ref?act('referral','查看内推','btn',`data-id="${id}"`):'')+act('save-opportunity','存入我的机会','btn',`data-id="${id}"`)+act('apply-job','记录申请','btn',`data-id="${id}"`)+act('tailor','准备定向简历','btn primary',`data-id="${id}"`))};
function opportunities(){const list=state.opportunities.filter(o=>o.mode===mode&&(o.company+o.job+o.note).includes(query));return head('我的机会','自己的机会清单：官网、朋友推荐、猎头沟通，都可以记在这里。',act('opportunity-new',I('plus')+' 记录机会','btn primary'))+toolbar('搜索公司、岗位或备注',['全部'])+`<div class="stack">${list.map(o=>`<section class="card"><div class="row between"><div><h2>${E(o.company)} · ${E(o.job)}</h2><p class="label">${E(o.source)} · 仅自己可见</p></div>${pill(o.converted?'已关联投递':'待考虑','blue')}</div><p class="op-note">${E(o.note)}</p><div class="row">${safeUrl(o.url)?`<a class="btn" href="${E(safeUrl(o.url))}" target="_blank" rel="noopener noreferrer">打开原文 ↗</a>`:''}${act('opportunity-edit','编辑','btn',`data-id="${o.id}"`)}${act('opportunity-apply',o.converted?'查看投递':'转为投递记录','btn primary',`data-id="${o.id}"`)}</div></section>`).join('')||empty('先记录一个值得考虑的机会。它不会出现在公开招聘列表。')}</div>`}
function opportunityForm(id){const o=state.opportunities.find(x=>x.id===id);formModal(o?'编辑机会':'记录私人机会',field('公司','company',o?.company)+field('岗位','job',o?.job)+selectField('来源','source',['官网','招聘网站','朋友推荐','猎头沟通','其他'],o?.source)+`<label class="field"><span>原文链接（可选）</span><input type="url" name="url" value="${E(o?.url||'')}"></label>`+textField('备注','note',o?.note),'保存到我的机会',f=>{const x=Object.fromEntries(f);if(o)Object.assign(o,x);else state.opportunities.push({id:uid(),mode,...x});persist();close();render()})}
const templates=[{id:'classic',name:'中文简洁',hint:'清楚、紧凑，适合技术岗位',cost:'免费'},{id:'modern',name:'蓝线强调',hint:'突出技能与项目结构',cost:'免费'},{id:'serif',name:'经典英文',hint:'英文排版与清晰层级',cost:'免费'}];
function resumeWizard(source='',jobId=''){const c=availableJobs().find(x=>x.id===jobId);formModal(c?'创建岗位定向简历':'新建简历 · 模板与内容',field('简历名称','name',c?c.name+' · 定向版':'我的新简历')+`<h3>1. 选择模板</h3><div class="template-options">${availableTemplates().map((t,i)=>`<label class="template-choice"><input type="radio" name="template" value="${t.id}" ${t.id===(state.defaultTemplate||'classic')?'checked':''}><span class="template-thumb ${t.id}">Aa<br><i></i><i></i><i></i></span><strong>${t.name}</strong><span class="meta">${t.cost}</span></label>`).join('')}${state.purchases.map(id=>`<label class="template-choice"><input type="radio" name="template" value="market-${id}"><span class="template-thumb modern">Aa<br><i></i><i></i></span><strong>${E(products.find(p=>p.id===id)?.title||'已购模板')}</strong><span class="meta">已购买</span></label>`).join('')}</div>${act('template-import','导入自己的模板','text-btn')}${act('my-templates','管理我的模板','text-btn')}${act('browse-templates','去市场挑选更多模板','text-btn')}<h3 style="margin-top:20px">2. 导入自己的内容</h3>`+selectField('信息来源','source',[['','从空白填写'],...state.resumes.map(r=>[r.id,r.name])],source)+`<p class="note">复制内容和经历显隐设置，建立独立版本线。点击创建之前不会生成简历。</p>`,'创建并编辑',f=>{const src=state.resumes.find(r=>r.id===f.get('source')),x=src?clone(src):newResume(f.get('name'));x.id=uid();x.name=f.get('name').trim();x.template=f.get('template');x.templateSpec=clone(templateDesign(x.template));x.kind=c?'岗位定向':'通用简历';x.versions=[];x.visibility={};delete x.showcase;if(!src){x.person='';x.headline='';x.education='';x.contact='';x.experiences=[];x.skills=''}state.resumes.push(x);checkpoint(x,src?'从 '+src.name+' 导入内容':'创建空白简历');selectedResume=x.id;editorTab='edit';persist();close();go('resumes')});document.getElementById('dialog').classList.add('wide')}
resumes=function(){if(!state.resumes.length)return head('我的简历','选择模板，开始填写。',act('new-resume','新建简历','btn primary'))+empty('还没有简历。')+act('resume-trash','查看回收站','btn');return oldResumeView()+`<div class="row" style="margin-top:16px">${act('resume-trash','回收站（'+state.trashedResumes.length+'）','text-btn')}</div>`};
resumePaper=function(r){let html=oldPaper(r).replace('class="resume-paper"',`class="resume-paper template-${E(r.template||'classic')}"`);if(r.lang==='en')html=html.replace('教育经历','Education').replace('专业技能','Skills');return html};
function visibilityForm(){const r=currentResume(),v=r.visibility||{};formModal('这份简历 · 可见范围',`<p class="note">默认私有。仅展示这份简历当前保存的快照，不开放其他简历、投递和复盘。</p><label class="check" style="margin:20px 0"><input name="hr" type="checkbox" ${v.hr?'checked':''}>允许已核验企业招聘者发现（${modes[mode].label}）</label>${mode==='social'?`<label class="check"><input name="hunter" type="checkbox" ${v.hunter?'checked':''}>允许已核验猎头发现（仅社招）</label>`:'<p class="label">实习 / 校招不向猎头开放。</p>'}<p class="label" style="margin-top:20px">后续修改不会悄悄更新展示内容；再次保存才更新快照。联系方式需另行授权。</p>`,'保存展示快照',f=>{r.visibility={hr:f.has('hr'),hunter:mode==='social'&&f.has('hunter'),mode,updated:dayKey()};r.showcase=clone({...r,versions:[],showcase:undefined});if(mode==='social'){state.discovery=f.has('hunter');state.discoveryResume=r.id}persist();close();render();toast('已保存可见范围与展示快照（本机演示）')})}
function eventForm(id){const e=state.events.find(x=>x.id===id);formModal(e?'编辑面试日程':'添加面试日程',field('公司','company',e?.company||'')+field('岗位','job',e?.job||modes[mode].role)+selectField('技术方向','track',['后端','数据','前端','算法','其他'],e?.track)+field('轮次','round',e?.round||'技术一面')+`<div class="two-col">${field('日期','date',e?.date||selectedDay,'date')}${field('时间','time',e?.time||'14:00','time')}</div>`+field('地点 / 方式','location',e?.location||'视频面试')+selectField('准备使用的简历','resumeId',state.resumes.map(r=>[r.id,r.name]),e?.resumeId)+selectField('状态','status',['待参加','已结束','已取消'],e?.status),'保存日程',f=>{const x=Object.fromEntries(f);if(e)Object.assign(e,x);else state.events.push({id:uid(),mode,...x});persist();close();render()})}
function eventDetail(id){const e=state.events.find(x=>x.id===id);if(!e)return;const r=state.resumes.find(r=>r.id===e.resumeId);modal(E(e.company)+' · '+E(e.round),`<div class="row between"><h3>${E(e.job)}</h3>${pill(e.status,'blue')}</div><p class="op-note">${E(e.date)} ${E(e.time)} · ${E(e.location)}</p><p class="note">准备材料：${E(r?.name||'未关联简历')}<br>可从岗位方向对应的公开面经抽题，也可用自己的题单。</p><div class="service-grid" style="margin-top:20px"><section class="card"><h3>AI 模拟面试</h3><p class="label">语音 / 文字问答，结束自动归档。</p>${act('mock-setup','配置并开始','btn primary',`data-id="${id}"`)}</section><section class="card"><h3>人工模拟面试</h3><p class="label">携带这场面试的目标预约教练。</p>${act('event-human','选择面试教练','btn',`data-id="${id}"`)}</section></div>`,act('event-edit','编辑日程','btn',`data-id="${id}"`)+act('event-review','写这场面试的复盘','btn',`data-id="${id}"`));document.getElementById('dialog').classList.add('wide')}
practice=function(){const es=ownEvents().filter(e=>(e.company+e.job+e.round).includes(query));const active=state.sessions.filter(s=>s.mode===mode&&!s.finished);return head('面试与模拟','选择一场面试，准备、练习，再把收获留下。',act('new-event',I('plus')+' 添加面试日程','btn primary'))+toolbar('搜索公司、岗位或轮次',['全部'])+(active.length?`<section class="card" style="margin-bottom:20px"><h3>继续未完成的模拟</h3>${active.map(s=>`<div class="task"><div class="grow"><strong>${E(s.title)}</strong><p class="meta">已回答 ${s.answers.length} / ${s.questions.length} 题</p></div>${act('resume-chat','继续练习','btn',`data-id="${s.id}"`)}</div>`).join('')}</section>`:'')+`<div class="stack">${es.map(e=>`<section class="card"><div class="row between"><div><span class="eyebrow">${E(e.date)} · ${E(e.time)}</span><h2 style="margin-top:8px">${E(e.company)} · ${E(e.round)}</h2><p class="label">${E(e.job)} · ${E(e.location)} ${e.sample?'· 示例日程':''}</p></div>${pill(e.status,e.status==='已结束'?'green':'blue')}</div><div class="row" style="margin-top:20px">${act('mock-setup',I('spark')+' AI 模拟面试','btn primary',`data-id="${e.id}"`)}${act('event-human','人工模拟面试','btn',`data-id="${e.id}"`)}${act('event','日程与准备材料','btn',`data-id="${e.id}"`)}${act('event-review','写复盘','text-btn',`data-id="${e.id}"`)}</div></section>`).join('')||empty('添加第一场面试，也可以为一次自选练习创建日程。')}</div>`};
function matchingPosts(e){return state.posts.filter(p=>p.published&&p.consent&&p.track===e.track&&p.mode===mode)}
function setupMock(id){const e=state.events.find(x=>x.id===id);if(!e)return;const posts=matchingPosts(e),same=posts.filter(p=>p.company===e.company);formModal('配置模拟 · '+E(e.company),`<p class="note">AI 问答流程原型：使用本机样例题库与规则反馈，尚未接入大模型。浏览器支持时可朗读和语音转文字。</p>`+selectField('出题方式','method',[['auto','按岗位方向从公开面经组卷'],['custom','只使用我的题目'],['mixed','面经题目 + 自定义题目']])+selectField('题目数量','count',['3','5','8'])+`<label class="field"><span>面经范围</span><select name="scope"><option value="company">优先同公司，不足用同方向补充</option><option value="track">同方向与同求职阶段</option></select></label><p class="label">同公司 ${same.length} 篇 / 同方向 ${posts.length} 篇可用面经。题量不足会明确标记基础补充题。</p>`+textField('自定义题目（每行一题）','custom','','例如：解释你最近项目的技术难点。\n你会如何排查慢查询？')+`<label class="check"><input name="read" type="checkbox">开启题目朗读</label><p class="meta" style="margin-top:12px">简历只读取所选版本；私人复盘不会进入公共题库。</p>`,'开始模拟',f=>{const method=f.get('method'),custom=String(f.get('custom')).split('\n').map(x=>x.trim()).filter(Boolean);if(method==='custom'&&!custom.length){document.getElementById('form-error').textContent='请至少填写一道自定义题。';return}const ordered=f.get('scope')==='company'?[...same,...posts.filter(p=>p.company!==e.company)]:posts;let qs=method==='custom'?[]:ordered.flatMap(p=>p.questions.map(q=>({q,source:p.title,postId:p.id})));qs=qs.filter((x,i,arr)=>arr.findIndex(y=>y.q===x.q)===i);if(method!=='auto')qs=[...custom.map(q=>({q,source:'自定义题目'})),...qs];const n=Number(f.get('count'));if(method!=='custom'){const fallback=[`请结合${e.job}，介绍你最相关的一段经历。`,'你在项目中做过什么技术取舍？','如果重新做这个项目，你会改进什么？','如何验证你的方案有效？','你如何与同事处理意见分歧？','遇到生产故障时你如何排查？','你还有什么希望向团队了解的问题？','请说明一个失败的尝试以及复盘。'];for(const q of fallback)if(qs.length<n)qs.push({q,source:'通用基础补充题（非公司真题）'})}qs=qs.slice(0,n);const r=state.resumes.find(r=>r.id===e.resumeId);const s={id:uid(),mode,eventId:id,title:e.company+' · '+e.round+'模拟',questions:qs,answers:[],draft:'',resume:r?clone(r):null,date:dayKey(),finished:false};state.sessions.push(s);activeSession=s.id;voiceEnabled=f.has('read');persist();close();go('chat');if(voiceEnabled)speakQuestion()})}
function stopVoice(){if(recognition){recognition.abort();recognition=null}listening=false;window.speechSynthesis?.cancel()}
function speakQuestion(){const s=state.sessions.find(x=>x.id===activeSession);if(!s)return;if(!window.speechSynthesis){toast('当前浏览器不支持朗读，可以阅读题目继续');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s.questions[s.answers.length]?.q||'本次练习结束。');u.lang='zh-CN';u.onerror=()=>toast('朗读不可用，仍可使用文字练习');window.speechSynthesis.speak(u)}
function chatView(){const s=state.sessions.find(x=>x.id===activeSession);if(!s)return head('AI 模拟面试','从面试日程中开始一场模拟。')+act('prepare','选择面试','btn primary');const idx=s.answers.length,q=s.questions[idx];return head(s.title,'练习记录自动保存，随时可以暂停。',act('chat-pause','暂停并返回','btn')+act('chat-end','结束并整理复盘','btn primary'))+`<div class="chat-layout"><section class="card chat-panel"><div class="chat-meta"><span class="avatar">AI</span><div><strong>模拟面试官</strong><p class="meta">样例问答流程 · 未接入大模型</p></div>${pill(`${Math.min(idx+1,s.questions.length)} / ${s.questions.length} 题`,'blue')}</div><div class="chat-transcript">${s.answers.map((a,i)=>`<div class="message interviewer"><span class="meta">面试官 · ${E(s.questions[i].source)}</span><p>${E(s.questions[i].q)}</p></div><div class="message candidate"><span class="meta">我的回答</span><p>${E(a)}</p></div>`).join('')}${q?`<div class="message interviewer current"><span class="meta">面试官 · ${E(q.source)}</span><h3>${E(q.q)}</h3></div>`:'<div class="note">所有题目都已回答，可以结束并整理复盘。</div>'}</div>${q?`<div class="chat-composer"><label class="field"><span>你的回答 · 语音转写后可修改</span><textarea id="chat-answer" placeholder="写下思路，或点击语音输入…">${E(s.draft||'')}</textarea></label><p id="voice-status" class="meta" role="status">麦克风未开启</p><div class="row between"><div class="row">${act('read-question','朗读题目','btn')}${act('mic','语音输入','btn','id="mic-button"')}</div>${act('send-answer',idx===s.questions.length-1?'提交最后一题':'提交回答，下一题','btn primary')}</div></div>`:''}</section><aside class="stack"><section class="card"><h3>这场练习的上下文</h3><p class="op-note">${E(s.resume?.name||'未关联简历')}</p><p class="label">题目来源在每道问题上标注。自定义题严格按你的题单提问。</p></section><section class="card"><h3>结束后会得到什么？</h3><ul class="clean-list"><li>完整题目与自己的回答</li><li>标明来源的参考思路</li><li>本场总结与下一步建议</li><li>自动保存的私密 Markdown 复盘</li></ul><p class="meta">当前建议是规则示例，不能替代专业评估。</p></section></aside></div>`}
function startMic(){const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C){toast('当前浏览器不支持语音识别，请用文字作答；可在支持的浏览器体验语音');return}if(listening){recognition?.stop();return}window.speechSynthesis?.cancel();const el=document.getElementById('chat-answer'),prefix=el.value;recognition=new C();recognition.lang='zh-CN';recognition.interimResults=true;recognition.continuous=true;recognition.onresult=e=>{let text='';for(let i=0;i<e.results.length;i++)text+=e.results[i][0].transcript;el.value=prefix+(prefix?'\n':'')+text;saveChatDraft()};recognition.onstart=()=>{listening=true;document.getElementById('voice-status').textContent='正在听你说话… 完成后点击停止语音';document.getElementById('mic-button').textContent='停止语音'};recognition.onend=()=>{listening=false;const s=document.getElementById('voice-status');if(s)s.textContent='语音已停止，可以修改转写后提交';const b=document.getElementById('mic-button');if(b)b.textContent='语音输入'};recognition.onerror=e=>{toast(e.error==='not-allowed'?'麦克风未授权，请用文字继续':'语音识别暂不可用，请用文字继续')};try{recognition.start()}catch{toast('无法启动语音，请用文字继续')}}
function referenceFor(q){if(/重复|幂等/.test(q))return '先定义重复请求的边界，再说明业务唯一键、数据库约束与事务；补充超时重试和并发测试。不要只依赖前端禁用按钮。';if(/缓存/.test(q))return '区分穿透、击穿与雪崩；结合负载解释过期抖动、互斥重建和降级，说明一致性取舍。';if(/SQL|慢查询|数据/.test(q))return '先确认数据规模与目标，再查看执行计划或数据血缘；用抽样、唯一性和完整性校验验证结果。';return '按背景与约束 → 个人职责 → 选择与取舍 → 验证与结果展开。用真实例子支撑，说明还不确定的部分。'}
function finishMock(){const s=state.sessions.find(x=>x.id===activeSession);if(!s||s.finished)return;saveChatDraft();if(s.draft.trim()&&s.answers.length<s.questions.length){s.answers.push(s.draft.trim());s.draft=''}stopVoice();const body=`# ${s.title}\n\n> AI 模拟流程记录。参考回答与总结为规则示例，未经模型评估。\n\n## 本场问答\n\n`+s.questions.map((x,i)=>`### ${i+1}. ${x.q}\n\n来源：${x.source}\n\n**我的回答**\n\n${s.answers[i]||'未作答'}\n\n**参考思路（示例）**\n\n${referenceFor(x.q)}\n`).join('\n')+`\n## 本场总结与建议\n\n- 已回答 ${s.answers.length} / ${s.questions.length} 题。\n- ${s.answers.filter(a=>a.length<40).length} 个回答较短，可补充一个具体决策与验证过程；长度不代表质量。\n- 优先重练未回答或不确定的问题，不使用未经验证的数字。\n\n## 我的补充复盘\n\n`;const r={id:uid(),title:s.title,body,mode,kind:'AI 模拟',tags:'模拟面试',eventId:s.eventId,sessionId:s.id,updated:dayKey()};state.reviews.push(r);s.finished=true;s.reviewId=r.id;selectedReview=r.id;persist();go('reviews');modal('本场记录已自动保存',`<p>题目、回答、参考思路和总结已进入私密复盘库。你可以补充自己的反思，也可以先跳过。</p>`,act('close','稍后补充','btn')+act('review-open','现在补充复盘','btn primary',`data-id="${r.id}"`))}
// Escapes HTML before rendering a deliberately small Markdown subset.
function markdown(src){let inCode=false;return String(src).split('\n').map(line=>{if(line.startsWith('```')){inCode=!inCode;return inCode?'<pre><code>':'</code></pre>'}let x=E(line);if(inCode)return x+'\n';x=x.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');x=x.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,t,u)=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${t}</a>`);if(/^### /.test(x))return '<h3>'+x.slice(4)+'</h3>';if(/^## /.test(x))return '<h2>'+x.slice(3)+'</h2>';if(/^# /.test(x))return '<h1>'+x.slice(2)+'</h1>';if(x.startsWith('&gt; '))return '<blockquote>'+x.slice(5)+'</blockquote>';if(/^[-*] /.test(x))return '<div class="md-bullet">• '+x.slice(2)+'</div>';return x?'<p>'+x+'</p>':'<br>'}).join('')+(inCode?'</code></pre>':'')}
function createReview(eventId){const e=state.events.find(e=>e.id===eventId);const r={id:uid(),mode,title:e?e.company+' · '+e.round+'复盘':'未命名复盘',tags:e?.track||'',eventId:eventId||'',kind:'真实面试',updated:dayKey(),body:'# 面试复盘\n\n## 问题与我的回答\n\n## 哪些回答可以更好\n\n## 待补充的知识\n\n## 下一步\n- '};state.reviews.push(r);selectedReview=r.id;persist();close();go('reviews')}
function reviewLibrary(){const rs=state.reviews.filter(r=>r.mode===mode&&(r.title+r.tags+r.body).toLowerCase().includes(query.toLowerCase())&&(filter==='全部'||r.kind===filter));const r=rs.find(r=>r.id===selectedReview);return head('复盘库','属于你的面试笔记。私密保存，公开分享时另建副本。',act('review-new',I('plus')+' 新建复盘','btn primary'))+toolbar('搜索标题、标签与全文',['全部','真实面试','AI 模拟'])+`<div class="notes-layout"><aside class="stack">${rs.map(x=>`<button class="card note-item ${r?.id===x.id?'active':''}" data-act="review-open" data-id="${x.id}"><strong>${E(x.title)}</strong><p class="meta">${E(x.kind)} · ${E(x.updated)}</p><span class="label">${E(x.tags||'未分类')}</span></button>`).join('')||empty('没有匹配复盘。')}</aside><section class="card note-editor">${r?`<div class="row between"><span class="meta" id="review-save">本机自动保存 · 仅自己可见</span><div class="row">${act('review-export','导出 .md','btn sm')}${act('review-share','转为面经草稿','btn sm')}</div></div><label class="field"><span>标题</span><input data-note="title" value="${E(r.title)}"></label><label class="field"><span>标签</span><input data-note="tags" value="${E(r.tags)}" placeholder="例如：Java、系统设计、项目表达"></label><div class="row between"><div class="tabs compact">${act('review-edit','Markdown 编辑',!reviewPreview?'active':'')}${act('review-preview','阅读预览',reviewPreview?'active':'')}</div>${act('review-ai',I('spark')+' AI 复盘助手','btn sm')}</div>${reviewPreview?`<article class="markdown">${markdown(r.body)}</article>`:`<label class="field"><span class="sr-only">复盘正文</span><textarea class="markdown-source" data-note="body">${E(r.body)}</textarea></label>`}${r.ai?`<section class="ai-note"><div class="row between"><h3>AI 建议 · 规则示例</h3>${act('ai-to-note','插入复盘末尾','text-btn')}</div><article class="markdown">${markdown(r.ai)}</article></section>`:''}`:'<div class="empty"><h2>把一次经历，变成下次的准备。</h2><p>选择左侧文档，或开始一份新复盘。支持标题、列表、引用、代码块和链接。</p></div>'}</section></div>`}
function reviewAdvice(r){const text=r.body,terms=['缓存','幂等','SQL','慢查询','系统设计','项目'].filter(x=>text.includes(x));return `## 知识与解答方向\n\n${terms.length?terms.map(t=>`### ${t}\n${referenceFor(t)}\n`).join('\n'):'先将问题、当时的回答和卡住的位置分开记录，才能定位需要补充的知识。'}\n\n## 参考表达\n\n“当时的约束是……，我负责……，比较过……后选择……，通过……验证。尚未验证的是……。”\n\n## 下次练习\n\n- 选一题重新回答，保留原答案用于对照。\n- 给结论补充原因、边界和反例。\n\n> 根据正文关键词生成的演示建议；不是事实核验或真实 AI 评分。`}
function community(){const list=state.posts.filter(p=>(role==='admin'||p.published||p.mine)&&(p.title+p.company+p.track+p.tags+p.body).includes(query)&&(filter==='全部'||(filter==='我的发布'?p.mine:p.mode===mode)));return head(role==='admin'?'面经审核':'面经社区',role==='admin'?'检查脱敏、授权与内容，再决定是否收录。':'看别人的面试过程，也分享自己的经验。',role==='user'?act('post-new',I('plus')+' 发布面经','btn primary'):'')+toolbar('搜索公司、岗位方向、标签或正文',['全部','当前求职阶段','我的发布'])+`<div class="post-grid">${list.map(p=>`<article class="card"><div class="row between">${pill(modes[p.mode]?.label||'通用','blue')}${pill(p.published?'已发布':p.status||'待审核',p.published?'green':'orange')}</div><h2 style="margin:16px 0">${E(p.title)}</h2><p class="label">${E(p.company)} · ${E(p.track)} · ${E(p.date)}</p><p class="op-note">${E(p.tags)}</p><div class="row between"><span class="meta">${E(p.author)}</span>${act('post-open','阅读面经','btn',`data-id="${p.id}"`)}</div>${role==='admin'&&!p.published?act('post-approve','审核通过（本机演示）','btn primary',`data-id="${p.id}"`):''}${p.mine?act('post-edit','编辑草稿','text-btn',`data-id="${p.id}"`):''}</article>`).join('')||empty('还没有匹配的面经。')}</div>`}
function postForm(id,review){const p=state.posts.find(p=>p.id===id);formModal('面经草稿 · 公开前请检查',field('标题','title',p?.title||review?.title||'')+field('公司','company',p?.company||'')+selectField('岗位方向','track',['后端','数据','前端','算法','其他'],p?.track)+selectField('求职阶段','mode',Object.entries(modes).map(([k,v])=>[k,v.label]),p?.mode||mode)+field('标签','tags',p?.tags||review?.tags||'面试')+textField('正文（Markdown）','body',p?.body||review?.body||'')+textField('可用于组卷的问题（每行一题）','questions',p?.questions?.join('\n')||'')+`<label class="check"><input name="consent" type="checkbox" ${p?.consent?'checked':''}>允许平台从这篇公开面经抽取问题用于模拟面试</label><label class="check" style="margin-top:14px"><input type="checkbox" required>已去除联系方式、保密内容和第三方个人信息</label><p class="note" style="margin-top:14px">默认匿名。提交后待审核；不会发布原始私密复盘。原型仅保存在本机。</p>`,'提交审核',f=>{if(!String(f.get('body')).trim()){document.getElementById('form-error').textContent='请填写面经正文';return}const x={title:f.get('title'),company:f.get('company'),track:f.get('track'),mode:f.get('mode'),tags:f.get('tags'),body:f.get('body'),questions:String(f.get('questions')).split('\n').filter(t=>t.trim()),consent:f.has('consent'),published:false,status:'待审核',author:'匿名用户',date:dayKey(),mine:true};if(p)Object.assign(p,x);else state.posts.push({id:uid(),...x});persist();close();go('community');toast('面经草稿已提交审核（本机演示）')});document.getElementById('dialog').classList.add('wide')}
function recruiterDesk(){const own=state.publicJobs.filter(j=>role==='admin'||j.owner===role);return head(role==='admin'?'平台岗位与审核':role==='hunter'?'受托招聘岗位':'企业招聘台',role==='hunter'?'仅发布已核验委托的社招岗位；推荐前逐次取得候选人授权。':'岗位发布、状态维护和候选人处理集中在这里。',act('job-new',I('plus')+' 新建招聘岗位','btn primary'))+`<section class="card privacy-banner"><span class="square-icon">${I('bag')}</span><div><h3>${role==='admin'?'平台管理员':role==='hunter'?'周以安 · 远川人才 · 邀请开通示例':'青禾科技 · 企业任职关系已核验（演示）'}</h3><p class="label">${role==='recruiter'?'认证与企业绑定后才可发布。只能处理本企业收到的申请和用户主动开放的材料。':'公开岗位与私人机会分开保存。'}</p></div></section><div class="stack" style="margin-top:20px">${own.map(j=>`<section class="card"><div class="row between"><div><h2>${E(j.name)} · ${E(j.job)}</h2><p class="label">${modes[j.mode].label} · ${E(j.city)} · ${E(j.salary)}</p></div>${pill(j.status,j.status==='已发布'?'green':'orange')}</div><div class="row" style="margin-top:18px">${act('job-edit','编辑','btn',`data-id="${j.id}"`)}${role==='admin'&&j.status==='待审核'?act('job-approve','审核通过并发布','btn primary',`data-id="${j.id}"`):''}${j.status==='已发布'?act('job-offline','下架','btn',`data-id="${j.id}"`):''}${act('job-applicants','申请记录','btn',`data-id="${j.id}"`)}</div></section>`).join('')||empty('从一份真实、清楚的岗位说明开始。新岗位提交后由平台审核。')}</div>${role==='recruiter'?`<section class="card" style="margin-top:24px"><h2>主动开放展示的简历</h2><p class="label">本机演示只读取求职者明确开放给 HR 的快照。</p>${state.resumes.filter(r=>r.visibility?.hr).map(r=>`<div class="task"><div class="grow"><h3>${E(r.name)}</h3><span class="meta">${modes[r.visibility.mode].label} · 联系方式未开放</span></div>${act('talent-preview','查看授权快照','btn',`data-id="${r.id}"`)}</div>`).join('')||'<p class="empty">暂无授权展示的材料。</p>'}</section>`:''}`}
function jobForm(id){if(!['recruiter','hunter','admin'].includes(role))return;const j=state.publicJobs.find(x=>x.id===id);if(j&&role!=='admin'&&j.owner!==role)return;const body=(role==='recruiter'?'<p class="note">发布企业：青禾科技 · 已核验演示身份</p>':field('招聘企业','name',j?.name||''))+field('岗位名称','job',j?.job||'')+selectField('招聘类型','mode',role==='hunter'?[['social','社会招聘']]:Object.entries(modes).map(([k,v])=>[k,v.label]),j?.mode||mode)+field('工作城市','city',j?.city||'杭州')+field('薪资范围','salary',j?.salary||'')+field('技术关键词','skills',j?.skills||'')+textField('岗位职责与要求','desc',j?.desc||'')+`<label class="field"><span>官网招聘原文链接（可选）</span><input type="url" name="official" value="${E(j?.official||'')}"></label><label class="check"><input type="checkbox" required>${role==='hunter'?'本岗位已完成企业委托核验':'我有权代表该企业发布此岗位'}</label>`;formModal('招聘岗位 · 提交审核',body,'提交审核',f=>{const x={...Object.fromEntries(f),name:role==='recruiter'?'青禾科技':f.get('name'),status:'待审核',owner:j?.owner||role,date:dayKey(),color:'#4069df',source:role==='hunter'?'猎头受托发布':role==='admin'?'平台收录':'企业招聘者发布'};x.initial=x.name.slice(0,1);if(j)Object.assign(j,x);else state.publicJobs.push({id:uid(),...x});persist();close();render();toast('已进入岗位审核队列（演示）')})}
function hunterDesk(){const list=state.resumes.filter(r=>r.visibility?.hunter&&r.visibility.mode==='social');return head('猎头工作台','经营受托岗位与候选人关系，每次推荐都有明确授权。',pill('人工邀请开通 · 演示','blue'))+`<div class="stats"><div class="card stat"><span>受托岗位</span><strong>${state.publicJobs.filter(j=>j.owner==='hunter').length}</strong></div><div class="card stat"><span>主动开放的人才</span><strong>${list.length}</strong></div><div class="card stat"><span>推荐授权请求</span><strong>${state.talentRequests.length}</strong></div></div><section class="card"><div class="section-head"><h2>社招人才 · 仅展示授权材料</h2>${act('hunter-jobs','管理受托岗位','btn')}</div>${list.map(r=>`<div class="task"><div class="grow"><h3>${E(r.name)}</h3><p class="label">${E(r.showcase?.headline)} · 联系方式隐藏</p></div>${act('talent-preview','查看快照','btn',`data-id="${r.id}"`)}${act('request-talent','申请推荐授权','btn primary',`data-id="${r.id}"`)}</div>`).join('')||'<div class="empty">暂无主动开放的社招资料。可在求职者社招简历的可见范围中体验授权。</div>'}</section><section class="card" style="margin-top:22px"><h2>推荐跟进</h2>${state.talentRequests.map(t=>`<div class="task"><div class="grow"><strong>${E(t.resumeName)} → ${E(t.company)}</strong><p class="label">${E(t.job)} · ${t.status}</p></div>${pill('未向企业发送')}</div>`).join('')||'<p class="empty">发起授权请求后在这里跟进。</p>'}</section><div class="note" style="margin-top:20px">不开放实习 / 校招人才、不批量导出私密资料。合作收费、核验与续费仍由负责人线下对接。</div>`}
provider=function(){return head('服务协作','无需经营复杂后台，围绕一张服务单确认和交付。',act('service-partner','联系平台负责人','btn'))+`<p class="note" style="margin-bottom:20px">当前演示为陈知远的单据视角。正式产品由平台发送单次限时协作链接；批量接单的合作方再开通可选工作台。</p>`+`<div class="stack">${state.orders.filter(o=>o.provider==='陈知远').map(o=>`<section class="card"><h2>${E(o.type)} · ${o.id}</h2><p class="label">${E(o.slot)} · ${E(o.status)}</p><p class="op-note">需求：${E(o.need)}</p><p class="note">只授权本单材料：${E(o.resumeName)}</p><div class="row" style="margin-top:18px">${o.status==='待确认'?act('order-step','确认接单','btn primary',`data-id="${o.id}"`):o.status==='待服务'?act('service-deliver','记录交付','btn primary',`data-id="${o.id}"`):pill('已完成','green')}</div>${o.delivery?`<p>${E(o.delivery)}</p>`:''}</section>`).join('')||empty('暂无需要确认的服务单。平台负责人可先与你线下协调。')}</div>`};
const englishMap={
 '林一舟':'Yizhou Lin','后端开发 · Java / Spring Boot / Redis':'Backend Development · Java / Spring Boot / Redis','江南理工大学 · 计算机科学与技术 · 本科 · 2023 — 2027':'Jiangnan Institute of Technology · B.Sc. in Computer Science · 2023–2027','linyizhou@example.com · 杭州':'linyizhou@example.com · Hangzhou',
 '青禾科技 · 后端研发实习':'Qinghe Technology · Backend Development Intern','轻舟 · 校园二手交易平台':'Qingzhou · Campus Marketplace','开源社区 · 文档维护':'Open-source Community · Documentation',
 [experienceSeed[0].body]:'Contributed to an internal task scheduling platform, implementing task status queries and retry handling. Used Java, Spring Boot and Redis for task caching and status synchronization.',
 [experienceSeed[1].body]:'Collaborated in a four-person team to build a campus marketplace. Owned product search and order modules, designing order state transitions and using transactions and idempotency checks to handle duplicate submissions.',
 [experienceSeed[2].body]:'Maintained technical documentation and issue reports. Added local setup instructions and frequently asked questions to help new contributors understand the project.'
};
function englishDraft(){const r=currentResume(),x=clone(r);let pending=0;const translate=t=>{if(!/[\u4e00-\u9fff]/.test(t||''))return t;if(englishMap[t])return englishMap[t];pending++;return '[Translation pending review] '+t};x.id=uid();x.name=r.name+' · English';x.lang='en';x.template='serif';x.templateSpec=clone(templateDesign('serif'));x.kind='英文版';x.versions=[];x.visibility={};delete x.showcase;for(const k of ['person','headline','education','contact','skills'])x[k]=translate(x[k]||'');x.experiences=x.experiences.map(e=>({...e,title:translate(e.title),body:translate(e.body)}));x.translationPending=pending;modal('英文简历 · 预览确认',`<p class="note">原型已提供样例内容的中英转换；自定义中文会保留并标记待译，不编造翻译。正式版将接入逐段翻译与事实核对。隐藏经历继续保持隐藏。</p><p class="label">${pending?'有 '+pending+' 段需要翻译确认':'样例内容已转换，请检查人名、校名与专业术语'}</p>${resumePaper(x)}`,act('close','取消','btn')+act('english-confirm','保存为独立英文简历','btn primary'));englishDraft.pending=x;document.getElementById('dialog').classList.add('wide')}
action=function(a,d={}){
 const r=currentResume();
 switch(a){
 case 'switch':if(role!=='user'){roleEntry();return}oldAction(a,d);return;
 case 'entry-hunter':modal('猎头专属入口',`<h3>邀请开通，专注社招招聘协作。</h3><p class="op-note">由平台负责人逐个对接，核验身份、机构和委托关系，确认合作后发放邀请。已有账号后进入猎头工作台。</p><p class="note">本版不接收真实证件或密码。下方体验已核验角色的工作流程。</p>`,act('close','返回','btn')+act('set-role','体验已邀请猎头','btn primary','data-id="hunter"'));return;
 case 'entry-recruiter':modal('企业招聘者入口',`<h3>代表你的企业，发布清楚可靠的机会。</h3><p class="op-note">正式版需核验企业主体及本人任职/招聘权限，绑定企业后才能发布岗位和处理申请。发布后进入平台审核。</p><p class="note">本版不接收真实企业资料或密码。可体验已核验企业 HR 的流程。</p>`,act('close','返回','btn')+act('set-role','体验已核验企业 HR','btn primary','data-id="recruiter"'));return;
 case 'role':roleEntry();return;
 case 'set-role':saveChatDraft();stopVoice();role=d.id;if(!mode)mode='campus';close();go({admin:'admin',provider:'provider',hunter:'hunterdesk',recruiter:'recruiter',user:'today'}[role]||'today');return;
 case 'service-partner':modal('服务合作 · 负责人对接',`<h3>简历修改 / 模拟面试 / 面试辅导</h3><p class="op-note">由负责人了解你的专业方向、服务样例、可接单时间与报价，确认合作规则后安排服务。</p><p class="note">无需先注册完整后台。每单通过限时协作链接确认需求、排期和交付。当前尚未配置真实对接联系方式。</p>`,act('set-role','体验单据协作','btn primary','data-id="provider"'));return;
 case 'todo-new':todoForm();return;case 'todo-edit':todoForm(d.id);return;
 case 'todo-delete':state.todos=state.todos.filter(t=>t.id!==d.id);persist();close();render();return;
 case 'day':selectedDay=d.id;render();return;
 case 'week-prev':weekShift--;render();return;case 'week-next':weekShift++;render();return;case 'week-now':weekShift=0;selectedDay=dayKey();render();return;
 case 'interest':formModal('我的求职偏好',field('方向','direction',state.interest.direction)+field('城市（空格分隔）','cities',state.interest.cities)+field('技术关键词','terms',state.interest.terms),'保存偏好',f=>{state.interest=Object.fromEntries(f);persist();close();render()});return;
 case 'new-resume':resumeWizard();return;case 'duplicate':resumeWizard(r?.id);return;case 'tailor':resumeWizard(r?.id,d.id);return;
 case 'browse-templates':close();go('market');return;
 case 'delete-resume':modal('将简历移入回收站？',`<p>${E(r.name)} 可以随时恢复，已有投递快照不会删除。招聘展示将同时关闭。</p>`,act('close','保留','btn')+act('delete-resume-confirm','移入回收站','btn danger'));return;
 case 'delete-resume-confirm':{r.visibility={};delete r.showcase;state.trashedResumes.push(r);state.resumes=state.resumes.filter(x=>x.id!==r.id);selectedResume=state.resumes[0]?.id;if(state.discoveryResume===r.id)state.discovery=false;persist();close();render();return}
 case 'resume-trash':modal('简历回收站',state.trashedResumes.map(x=>`<div class="task"><div class="grow"><h3>${E(x.name)}</h3><p class="meta">${x.versions.length} 个版本 · 展示权限已关闭</p></div>${act('resume-recover','恢复','btn',`data-id="${x.id}"`)}</div>`).join('')||'<p class="empty">回收站为空</p>');return;
 case 'resume-recover':{const x=state.trashedResumes.find(x=>x.id===d.id);state.resumes.push(x);state.trashedResumes=state.trashedResumes.filter(y=>y.id!==d.id);selectedResume=x.id;persist();close();render();return}
 case 'english':englishDraft();return;case 'english-confirm':{const x=englishDraft.pending;if(!x)return;state.resumes.push(x);checkpoint(x,'中文简历生成英文草稿');selectedResume=x.id;editorTab='edit';englishDraft.pending=null;persist();close();render();return}
 case 'visibility':visibilityForm();return;
 case 'discovery':if(!r){toast('请先创建简历');return}visibilityForm();return;
 case 'referral':oldAction(a,d);document.querySelector('#dialog .dialog-foot').insertAdjacentHTML('afterbegin',act('job','返回岗位详情','btn ghost',`data-id="${d.id}"`));return;
 case 'add-job':case 'opportunity-new':opportunityForm();return;case 'opportunity-edit':opportunityForm(d.id);return;
 case 'save-opportunity':{const j=availableJobs().find(x=>x.id===d.id);if(!state.opportunities.some(o=>o.jobId===j.id&&o.mode===mode))state.opportunities.push({id:uid(),mode,jobId:j.id,company:j.name,job:j.job,source:j.source,url:j.official||'',note:j.desc});persist();close();go('opportunities');return}
 case 'opportunity-apply':{const o=state.opportunities.find(x=>x.id===d.id);if(o.converted){go('applications');return}if(!r){toast('请先创建简历');return}formModal('转为投递记录',selectField('使用简历','resume',state.resumes.map(r=>[r.id,r.name]))+selectField('阶段','stage',['准备中','已投递']),'确认记录',f=>{const ap=addApplication(o.company,o.job,f.get('resume'),f.get('stage'));o.converted=ap.id;persist();close();go('applications')});return}
 case 'apply-job':{const j=availableJobs().find(x=>x.id===d.id);if(!r){toast('请先创建简历');return}formModal('记录岗位申请',selectField('材料版本','resume',state.resumes.map(r=>[r.id,r.name]))+selectField('当前状态','stage',['准备中','已投递'])+'<p class="note">不自动向企业发送。选择已投递表示你确认已提交，本机模拟招聘侧收到的申请。</p>','保存记录',f=>{const ap=addApplication(j.name,j.job,f.get('resume'),f.get('stage'));if(f.get('stage')==='已投递')state.recruitmentApplications.push({id:uid(),jobId:j.id,applicationId:ap.id,resume:clone(ap.snapshot),status:'待查看'});persist();close();go('applications')});return}
 case 'new-event':eventForm();return;case 'event-edit':eventForm(d.id);return;case 'event':eventDetail(d.id);return;
 case 'event-review':createReview(d.id);return;case 'review-new':case 'review':createReview();return;
 case 'event-human':{const e=state.events.find(x=>x.id===d.id);state.bookingContext={eventId:e.id,title:e.company+' · '+e.round};persist();close();page='services';filter='模拟面试';serviceView='browse';render();return}
 case 'book':oldAction(a,d);if(state.bookingContext){document.querySelector('#modal-form').insertAdjacentHTML('afterbegin',`<p class="note">准备目标：${E(state.bookingContext.title)}</p>`);const need=document.querySelector('[name="need"]');need.value='为 '+state.bookingContext.title+' 做模拟练习。'}return;
 case 'confirm-notice-done':if(!ownEvents().some(e=>e.notice==='xy'))state.events.push({id:uid(),mode,notice:'xy',company:'星野网络',job:modes[mode].role,track:'后端',round:'在线笔试',date:'2026-09-18',time:'19:00',location:'线上考试',resumeId:r?.id,status:'待参加'});oldAction(a,d);return;
 case 'prepare':close();go('practice');return;
 case 'mock-setup':setupMock(d.id);return;case 'resume-chat':activeSession=d.id;close();go('chat');return;
 case 'chat-pause':saveChatDraft();stopVoice();go('practice');return;
 case 'read-question':speakQuestion();return;
 case 'mic':if(listening){recognition?.stop();return}if(!(window.SpeechRecognition||window.webkitSpeechRecognition)){toast('当前浏览器不支持语音识别，请使用文字回答');return}modal('启用语音输入',`<p>浏览器会请求麦克风权限。部分浏览器将音频交给其语音识别服务处理；平台原型仅保存转写文字，不存录音。</p><p class="note">不想开启也可以直接打字完成模拟。</p>`,act('close','继续打字','btn')+act('mic-start','开启语音','btn primary'));return;
 case 'mic-start':close();startMic();return;
 case 'send-answer':{const s=state.sessions.find(x=>x.id===activeSession),answer=document.getElementById('chat-answer').value.trim();if(!answer){toast('请先回答，再提交');return}stopVoice();s.answers.push(answer);s.draft='';persist();render();if(voiceEnabled)speakQuestion();return}
 case 'chat-end':saveChatDraft();modal('结束本次模拟？','<p>未提交的当前回答会一并保存。未回答题目标注为未作答，不生成虚构回答。</p>',act('close','继续练习','btn')+act('chat-finish','结束并生成复盘','btn primary'));return;
 case 'chat-finish':close();finishMock();return;
 case 'review-open':selectedReview=d.id;reviewPreview=false;close();go('reviews');return;case 'review-edit':reviewPreview=false;render();return;case 'review-preview':reviewPreview=true;render();return;
 case 'review-ai':{const n=state.reviews.find(x=>x.id===selectedReview);n.ai=reviewAdvice(n);persist();render();return}
 case 'ai-to-note':{const n=state.reviews.find(x=>x.id===selectedReview);n.body+='\n\n'+n.ai;n.ai=null;persist();render();return}
 case 'review-export':{const n=state.reviews.find(x=>x.id===selectedReview),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([n.body],{type:'text/markdown;charset=utf-8'}));a.download=n.title+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return}
 case 'review-share':postForm(null,state.reviews.find(x=>x.id===selectedReview));return;
 case 'post-new':postForm();return;case 'post-edit':postForm(d.id);return;
 case 'post-open':{const p=state.posts.find(p=>p.id===d.id);modal(E(p.title),`<p class="label">${E(p.company)} · ${E(p.track)} · ${E(p.author)}</p><article class="markdown">${markdown(p.body)}</article><p class="note">${p.consent?'作者允许本篇问题用于模拟面试':'未授权组卷，仅供阅读'}</p>`);document.getElementById('dialog').classList.add('wide');return}
 case 'post-approve':if(role!=='admin')return;{const p=state.posts.find(p=>p.id===d.id);p.published=true;p.status='已发布';persist();render();return}
 case 'hunter-jobs':go('recruiter');return;case 'job-new':jobForm();return;case 'job-edit':jobForm(d.id);return;
 case 'job-approve':if(role!=='admin')return;{const j=state.publicJobs.find(j=>j.id===d.id);j.status='已发布';persist();render();return}
 case 'job-offline':{const j=state.publicJobs.find(j=>j.id===d.id);if(role==='admin'||j.owner===role){j.status='已下架';persist();render()}return}
 case 'job-applicants':{const j=state.publicJobs.find(j=>j.id===d.id);if(role!=='admin'&&j.owner!==role)return;const apps=state.recruitmentApplications.filter(x=>x.jobId===d.id);modal('收到的申请 · '+E(j.job),apps.map(x=>`<section class="card"><h3>${E(x.resume.person)}</h3><p>${E(x.resume.headline)}</p><p class="label">${x.status} · 主动投递材料</p>${act('applicant-open','查看材料','btn',`data-id="${x.id}"`)}</section>`).join('')||'<p class="empty">暂无申请。仅显示本岗位收到的材料，不读取求职者私密空间。</p>');return}
 case 'applicant-open':{const x=state.recruitmentApplications.find(x=>x.id===d.id);const j=state.publicJobs.find(j=>j.id===x?.jobId);if(!j||(role!=='admin'&&j.owner!==role))return;x.status='已查看';persist();modal('申请材料',resumePaper(x.resume),act('applicant-next','标记进入沟通','btn primary',`data-id="${x.id}"`));return}
 case 'applicant-next':{const x=state.recruitmentApplications.find(x=>x.id===d.id);const j=state.publicJobs.find(j=>j.id===x?.jobId);if(!j||(role!=='admin'&&j.owner!==role))return;x.status='进入沟通';persist();close();toast('已记录沟通阶段，未发送外部消息');return}
 case 'talent-preview':{const x=state.resumes.find(x=>x.id===d.id),v=x.showcase;if(!v)return;const cp=clone(v);cp.contact='联系方式未授权';modal('授权展示快照',resumePaper(cp));return}
 case 'request-talent':{const x=state.resumes.find(x=>x.id===d.id),js=state.publicJobs.filter(j=>j.owner==='hunter'&&j.status==='已发布');if(!js.length){toast('先添加并完成审核一份受托社招岗位');return}formModal('申请单次推荐授权',selectField('具体公司与岗位','job',js.map(j=>[j.id,j.name+' · '+j.job]))+'<p class="note">此处仅请求候选人授权，不向企业发送资料。</p>','记录授权请求',f=>{const j=js.find(j=>j.id===f.get('job'));state.talentRequests.push({id:uid(),resumeId:x.id,resumeName:x.name,company:j.name,job:j.job,status:'等待候选人确认'});persist();close();render()});return}
 case 'service-deliver':formModal('服务交付',textField('交付说明','delivery','','填写本单完成的内容与后续约定'),'保存交付记录',f=>{const o=state.orders.find(o=>o.id===d.id);if(!String(f.get('delivery')).trim())return;o.delivery=f.get('delivery');o.status='已完成';persist();close();render()});return;
 case 'reset-confirm':stopVoice();oldAction(a,d);migrate();persist();render();return;
 }
 oldAction(a,d);
};
document.addEventListener('input',e=>{if(e.target.dataset.note){const r=state.reviews.find(x=>x.id===selectedReview);r[e.target.dataset.note]=e.target.value;r.updated=dayKey();persist();document.getElementById('review-save').textContent='已自动保存 · 仅自己可见'}if(e.target.id==='chat-answer')saveChatDraft()});
document.addEventListener('change',e=>{if(e.target.dataset.todo){state.todos.find(t=>t.id===e.target.dataset.todo).done=e.target.checked;persist();render()}});
window.addEventListener('pagehide',()=>{saveChatDraft();stopVoice()});
const baseChooseMode=chooseMode;chooseMode=function(m){saveChatDraft();stopVoice();baseChooseMode(m)};
const baseApplications=applications;
applications=function(){if(appView!=='calendar')return baseApplications();return head('投递管理 · 日历','与面试日程使用同一份记录。',act('new-event','添加面试日程','btn primary'))+`<div class="tabs compact">${act('app-view','看板','', 'data-id="board"')}${act('app-view','表格','', 'data-id="table"')}${act('app-view','日历','active','data-id="calendar"')}</div><div style="max-width:740px;margin-top:24px">${weekCalendar()}</div>`};
const baseHunters=hunters;
hunters=function(){return baseHunters()+`<section class="card" style="margin-top:22px"><h2>待确认的推荐授权</h2><p class="label">每次授权限定到具体企业、岗位和这份材料，不影响其他简历。</p>${state.talentRequests.filter(t=>t.status==='等待候选人确认').map(t=>`<div class="task"><div class="grow"><h3>${E(t.company)} · ${E(t.job)}</h3><p class="label">${E(t.resumeName)}</p></div>${act('talent-respond','同意这次推荐','btn primary',`data-id="${t.id}" data-answer="同意"`)}${act('talent-respond','拒绝','btn',`data-id="${t.id}" data-answer="拒绝"`)}</div>`).join('')||'<p class="empty">暂无等待确认的推荐请求。</p>'}</section>`};
const iterationAction=action;
action=function(a,d={}){if(a==='talent-respond'){const t=state.talentRequests.find(t=>t.id===d.id);if(role!=='user'||mode!=='social'||!t)return;t.status=d.answer==='同意'?'候选人已授权（未发送）':'候选人已拒绝';if(d.answer==='同意'){const r=state.resumes.find(r=>r.id===t.resumeId);t.snapshot=r?.showcase?clone(r.showcase):null}persist();render();return}iterationAction(a,d)};
const initialPage=location.hash.slice(1);if(mode&&navItems().some(n=>n[0]===initialPage))page=initialPage;
render();
if(initialPage==='entry-hunter'||initialPage==='entry-recruiter')action(initialPage);
if(initialPage==='entry-service')action('service-partner');
